'@

$catalog = $catalogJson | ConvertFrom-Json
$catalog | Add-Member -NotePropertyName generatedAt -NotePropertyValue ((Get-Date).ToUniversalTime().ToString('yyyy-MM-ddTHH:mm:ssZ')) -Force
foreach ($crop in $catalog.crops) {
    $crop.name = $crop.name.Trim()
    $crop.ecology | Add-Member -NotePropertyName growingDegreeDaysToMaturity -NotePropertyValue $null -Force
    $crop.ecology | Add-Member -NotePropertyName baseTemperatureC -NotePropertyValue $null -Force
    $crop.ecology | Add-Member -NotePropertyName plantingWindowByCountryAndAgroecologicalZone -NotePropertyValue $null -Force
    $crop | Add-Member -NotePropertyName hazards -NotePropertyValue ([pscustomobject]@{
        heatStressThresholdByStageC = $null
        frostSensitivityClass = $null
        extremeRainfallSensitivity = $null
        windAndHailSensitivity = $null
    }) -Force
    $crop.soilRotation | Add-Member -NotePropertyName npkRemovalPerTonne -NotePropertyValue $null -Force
    $crop.soilRotation | Add-Member -NotePropertyName nutrientDemandClass -NotePropertyValue $null -Force
}
$catalog.sources += [pscustomobject]@{
    id = 'FAO_CROP_CALENDAR'
    name = 'FAO Crop Calendar'
    url = 'https://cropcalendar.apps.fao.org/'
    use = 'Country- and agroecological-zone-specific sowing and harvest windows; availability varies by crop and country.'
}
$output = Join-Path $PSScriptRoot 'crop_catalog.json'
$json = ConvertTo-Json -InputObject $catalog -Depth 100
[IO.File]::WriteAllText($output, $json, [Text.UTF8Encoding]::new($false))
Write-Output "Wrote focused catalog with $($catalog.crops.Count) crops to $output"
